// th16_s1_w04 — TH16 v1.00a st01.ecl MainSub03:1218-1257
// Early-kill reward formation: 4 rounds x (10 + 10) Phantom01 spawns from a top arc,
// each ghost drifts outward and keeps firing along its final movement angle.
// Source positions/frames are noted next to each translated statement.

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// transcribe/th16/touhou-bullets.ecl: src etSprite(0, 5, 4)
const TH16_BALL2: int = 432;
const SHOT_COLOR: int = 4;

// src enmCreateF("Phantom01", x, 32.0f, 120, 1000, 1)
const PHANTOM_HP: int = 120;
const PHANTOM_SCORE: int = 1000;

// src Phantom01_at: 0.17453292 rad second angle = 10 deg total spread, only H has 2 ways
const HALF_SPREAD: angle = 5deg;
// src moveEllipseRel omega 0.034906585 rad/frame = 2 deg/frame, r = 10
const WOBBLE_STEP_BAM: int = 364;
const WOBBLE_R: fx = 10fx;

// src etEx(0, 1, 8, 80, -999999, r, 0.0f): ANGLE_ACCEL, a=80 frames, omega=0
xformdef GHOST_ACCEL(acc: fx) {
    @80 set_accel(acc);
    set_accel(0fx);
}

// One source movement tick (movement phase runs before ECL there; here the next tick is
// armed at the end of the ECL frame so the positions seen by ECL match).
// ABS: moveVel(%F0, 0) + moveVelTime(60, 3, %F0, 2.0) -> speed 2*(k/60)^4 up to 2 px/f.
// REL: moveEllipseRel(%F0, 2deg/f, 10, 0, %ABS_ANGLE, 0) -> 10*sin(k*2deg) on the
//      perpendicular of %F0 (axis snapshot equals %F0: moveVel already set ABS angle).
sub arm_step() {
    set_self_int(2, self_int(3));
    var k: int = self_int(1) + 1;
    set_self_int(1, k);
    var dir: angle = self_int(0) as angle;
    var spd: fx = 2fx;
    if k < 60 {
        var u: fx = (k as fx) / 60fx;
        spd = 2fx * u * u * u * u;
    }
    var w: fx = WOBBLE_R * (sin((k * WOBBLE_STEP_BAM) as angle)
        - sin(((k - 1) * WOBBLE_STEP_BAM) as angle));
    var c: fx = cos(dir);
    var s: fx = sin(dir);
    var dx: fx = spd * c - w * s;
    var dy: fx = spd * s + w * c;
    // FINAL_ANGLE is the final (combined) movement direction of this tick.
    set_self_int(3, atan2(dy, dx) as int);
    move_vel_xy(0, dx, dy, EASE_LINEAR);
}

// src Phantom01_at: etNew/etAim(1)/etCountD/etAngle/etSpeedD + the shot loop.
async sub phantom_at(pregap: int, shots: int, gap: int, ways: int, spd: fx, acc: fx) {
    wait(pregap);
    for i in 0..shots {
        wait(gap);
        // src etAngle(0, %FINAL_ANGLE, 0.17453292f); etOn(0);
        var a: angle = self_int(2) as angle;
        if ways > 1 {
            // mode1 fixed fan, N=2, F = +/- delta/2
            var a1: angle = a - HALF_SPREAD;
            var a2: angle = a + HALF_SPREAD;
            // ANIM a=1 birth displacement: position -= 4*velocity
            _ = fire(TH16_BALL2, SHOT_COLOR,
                $self_x - 4fx * spd * cos(a1), $self_y - 4fx * spd * sin(a1),
                spd, a1, GHOST_ACCEL(acc), none);
            _ = fire(TH16_BALL2, SHOT_COLOR,
                $self_x - 4fx * spd * cos(a2), $self_y - 4fx * spd * sin(a2),
                spd, a2, GHOST_ACCEL(acc), none);
        } else {
            _ = fire(TH16_BALL2, SHOT_COLOR,
                $self_x - 4fx * spd * cos(a), $self_y - 4fx * spd * sin(a),
                spd, a, GHOST_ACCEL(acc), none);
        }
    }
}

// src Phantom01: judgment + movement; dropSeason/anmSelect/anmSetSprite/playSound/
// dropMain are reward/visual and omitted by the shared policy.
async sub phantom(dir: angle) {
    set_invuln(65535);
    // src setHurtbox(28,28) -> r 14; src setHitbox(16,16) -> r 8
    set_hurtbox(14fx);
    set_hitbox(8fx);
    set_self_int(0, dir as int);
    set_self_int(1, 0);
    set_self_int(2, dir as int);
    set_self_int(3, dir as int);

    var rank: int = global(GVAR_RANK);
    // etSpeedD speed0: E 1.0 / N 0.01 / H 1.0 / L 4.0
    var spd: fx = 1fx;
    // ANGLE_ACCEL r: E 0.0125 / N,H,L 0.0375
    var acc: fx = 0.0375fx;
    // etCountD ways: E 1 / N 1 / H 2 / L 1
    var ways: int = 1;
    // diffI($A): E 1 shot, else 100; wait: E 60 / N 60 / H 40 / L 30
    var shots: int = 100;
    var gap: int = 60;
    var pregap: int = 0;
    if rank == 0 {
        acc = 0.0125fx;
        shots = 1;
    } else if rank == 1 {
        spd = 0.01fx;
    } else if rank == 2 {
        ways = 2;
        gap = 40;
    } else {
        spd = 4fx;
        gap = 30;
    }
    if rank == 0 {
        pregap = 60;
    }

    arm_step();
    spawn phantom_at(pregap, shots, gap, ways, spd, acc);
    // src main task then waits 60 and loops wait(1000) forever; its movement keeps
    // ticking every frame in the original, so this task arms a tick every frame.
    loop { wait(1); arm_step(); }
}

// src MainSub03 spawn schedule: wait(180) then 4 rounds of
// (10 spawns 4 frames apart, wait 80, 10 mirrored spawns 4 frames apart, wait 80),
// then wait(50). C starts at 135deg and steps -12deg; A starts at -120 and steps +24.
// The mirrored group starts at 45deg / x=120 and steps +12deg / -24.
sub wave() {
    wait(180);
    for round in 0..4 {
        var c: angle = 135deg;
        var x: fx = -120fx;
        for i in 0..10 {
            _ = spawn_enemy(x, 32fx, PHANTOM_HP, 0, PHANTOM_SCORE, 0, phantom(c));
            c = c - 12deg;
            x = x + 24fx;
            wait(4);
        }
        wait(80);
        c = 45deg;
        x = 120fx;
        for j in 0..10 {
            _ = spawn_enemy(x, 32fx, PHANTOM_HP, 0, PHANTOM_SCORE, 0, phantom(c));
            c = c + 12deg;
            x = x - 24fx;
            wait(4);
        }
        wait(80);
    }
    wait(50);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
